// @castable/protocol: the wire types between the Rust core and every UI.
// Types only: no state, no logic. Each mirrors a serde type in
// crates/castable-core; fixtures/*.ts (generated by the Rust tests) type-check
// against these, so the two sides can't drift.
//
//   core ──ReceiverView──▶ UI          (what to show)
//   core ──PlayerCommand──▶ player     (what to play)
//   player ──PlayerEvent──▶ core       (what happened)
//   UI ──SenderCommand──▶ core         (remote/keyboard: play, pause, seek)

export type MediaKind = "video" | "audio" | "image";

/** How media is delivered. A live stream can't be seeked and has no duration. */
export type Delivery =
  | { type: "onDemand"; startAtSecs?: number }
  | { type: "live" };

export interface Subtitle {
  url: string;
  lang?: string;
  label?: string;
}

export interface MediaDescriptor {
  url: string;
  kind: MediaKind;
  mime?: string;
  title?: string;
  headers?: Record<string, string>;
  subtitles?: Subtitle[];
  delivery?: Delivery;
}

export const isLive = (m: MediaDescriptor): boolean => m.delivery?.type === "live";

/** UPnP AVTransport state as senders see it. */
export type TransportState =
  | "NO_MEDIA_PRESENT"
  | "STOPPED"
  | "TRANSITIONING"
  | "PLAYING"
  | "PAUSED_PLAYBACK";

/**
 * The receiver's session as the UI sees it: a discriminated union on `phase`,
 * serialized by `Session::view()` in crates/castable-core/src/session.rs. The core
 * computes `transportState`, so the UI never re-derives it.
 */
export type ReceiverView = { transportState: TransportState } & (
  | { phase: "idle" }
  | { phase: "loading"; media: MediaDescriptor; playWhenReady: boolean }
  | {
      phase: "loaded";
      media: MediaDescriptor;
      playback: "stopped" | "playing" | "paused";
      positionSecs: number;
      durationSecs?: number;
    }
  | { phase: "unloaded"; media: MediaDescriptor; error?: string }
);

/** Identifies one load; events from an older load are ignored by the core. */
export type Gen = number;

/** What the platform's player must do. Mirrors `PlayerCommand`. */
export type PlayerCommand =
  | { type: "load"; gen: Gen; media: MediaDescriptor }
  | { type: "play" }
  | { type: "pause" }
  | { type: "stop" }
  | { type: "seek"; toSecs: number };

/** What the player reports back. Mirrors `PlayerEvent`. */
export type PlayerEvent =
  | { type: "loaded"; gen: Gen; durationSecs?: number }
  | { type: "loadFailed"; gen: Gen; reason: string }
  | { type: "progress"; gen: Gen; positionSecs: number; durationSecs?: number }
  | { type: "ended"; gen: Gen };

/** Commands from a sender, or from the receiver's own remote and keyboard. Mirrors `SenderCommand`. */
export type SenderCommand =
  | ({ type: "setUri" } & MediaDescriptor)
  | { type: "play" }
  | { type: "pause" }
  | { type: "stop" }
  | { type: "seek"; toSecs: number };
